{
  "schemaVersion": 1,
  "id": "python-managed",
  "version": "0.1.0",
  "description": "通过独立运行时资源准备任务 Python；宿主无需预装 Python",
  "host": { "os": ["linux"], "arch": ["x64"] },
  "preparation": { "granularity": "capability" },
  "permissions": { "filesystem": "package-state-and-workspace", "network": false },
  "provides": [{ "id": "python.execute", "interfaceVersion": 1, "kind": "tools", "description": "在依赖的固定 Python 运行时上创建任务 venv 并执行代码", "instructions": "EXECUTE.md", "tools": [
    { "name": "python_run", "description": "Run code in a task venv backed by the approved Python runtime resource; standard library only.", "exposure": "on_activation", "parameters": { "type": "object", "properties": { "code": { "type": "string" } }, "required": ["code"], "additionalProperties": false } }
  ] }],
  "requires": [{ "id": "python.runtime", "interfaceVersion": 1, "phase": "runtime" }],
  "lifecycle": { "runtime": "node", "entry": "worker.mjs" }
}

import { rm } from 'node:fs/promises';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';
let raw = ''; for await (const chunk of process.stdin) raw += chunk;
const request = JSON.parse(raw);
const base = request.dependencies.find(d => d.id === 'python.runtime' && d.phase === 'runtime')?.resources.interpreter;
const interpreter = join(request.taskDir, 'venv', 'bin', 'python');
const run = (path, args) => spawnSync(path, ['-I', '-B', ...args], { cwd: request.workspace, env: process.env,
  encoding: 'utf8', timeout: 15000, killSignal: 'SIGKILL', maxBuffer: 32768 });
let response;
switch (request.operation) {
  case 'check': {
    const passed = typeof base === 'string' && run(interpreter, ['-c', 'import sys; assert sys.prefix != sys.base_prefix']).status === 0;
    response = { capabilities: { 'python.execute': { status: passed ? 'ready' : 'not_ready', checks: [{ name: 'isolated_venv_executes', passed }] } } }; break;
  }
  case 'prepare': {
    if (typeof base !== 'string') throw new Error('Missing python.runtime interpreter resource');
    const result = run(base, ['-m', 'venv', '--without-pip', join(request.taskDir, 'venv')]);
    if (result.error || result.status !== 0) throw new Error(`Private venv preparation failed: ${result.error?.message ?? result.stderr}`);
    response = { prepared: true }; break;
  }
  case 'invoke': {
    if (request.tool !== 'python_run' || !request.requested.includes('python.execute')) throw new Error('Unknown tool');
    const result = run(interpreter, ['-c', request.args.code]);
    if (result.error || result.status !== 0) throw new Error(`Python failed: ${result.error?.message ?? result.stderr}`);
    response = { exitCode: result.status, stdout: result.stdout, stderr: result.stderr }; break;
  }
  case 'release': await rm(request.taskDir, { recursive: true, force: true }); response = { released: true }; break;
  default: throw new Error('Unknown operation');
}
process.stdout.write(JSON.stringify(response));
